using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using TMPro;using LWS.TruckBowling;
namespace LWS.TruckSports {public sealed class SportsExpansionIntegrationSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();Keyboard keyboard;InputSettings original,probe;string folder;bool done,error;
 [RuntimeInitializeOnLoadMethod]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsExpansionIntegration")<0)return;var go=new GameObject("Twelve-sport integration validation");DontDestroyOnLoad(go);go.AddComponent<SportsExpansionIntegrationSmoke>();}
 SportsTestPreferences preferences;void Start(){preferences=new SportsTestPreferences();folder=SportsEvidencePaths.Folder("IntegrationEvidence");Directory.CreateDirectory(folder);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Integration software keyboard");InputSystem.QueueStateEvent(keyboard,new KeyboardState());Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string s,string trace,LogType type){if(type==LogType.Exception||type==LogType.Error){error=true;records.Add("ERROR "+s);}}void Check(bool condition,string label){if(!condition)throw new Exception(label);records.Add("PASS "+label);Debug.Log("TS_INTEGRATION_PASS "+label);}IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));}
 void Update(){if(done)return;try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator child){steps.Push(child);continue;}return;}Finish(error?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}void Finish(int code){done=true;preferences?.Dispose();Time.timeScale=1;File.WriteAllLines(Path.Combine(folder,"results.txt"),records);if(keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);Application.Quit(code);}
 void CheckText(GameObject page,string context){foreach(var t in page.GetComponentsInChildren<TMP_Text>()){if(!t.gameObject.activeInHierarchy||t.text.Length==0)continue;t.ForceMeshUpdate();if(t.isTextOverflowing)throw new Exception("UI text overflow "+context+" / "+t.name+" / "+t.text);}}
 IEnumerator Run(){yield return Delay(.6f);var front=FindAnyObjectByType<SportsFrontEnd>();Check(front!=null,"Truck Sports startup front end");front.Action("play");string[] keys={"billiards","hockey","bowling","airhockey","wallball","cornhole","cheese","dock","keepaway","keepawayfp","curling","basejump","terrier"};foreach(var key in keys)Check(front.pages[1].GetComponentsInChildren<SportsMenuAction>(true).Count(a=>a.action==key)==1,"one playable menu entry "+key);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Screen.SetResolution(size.x,size.y,false);yield return Delay(.35f);Capture("menu-"+size.x);CheckText(front.pages[1],"selection "+size.x);yield return Delay(.15f);}
  for(int cycle=0;cycle<2;cycle++)foreach(var key in keys){front=FindAnyObjectByType<SportsFrontEnd>();front.Action(key);yield return Delay(.7f);Check(FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length==1,"one listener "+key+" cycle"+cycle);Check(FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsInactive.Include).Length==1,"one input event system "+key+" cycle"+cycle);var m=FindAnyObjectByType<SportsEventSession>();if(m!=null){Check(m.menus.Screen==SportsEventScreen.Setup,"new sport setup "+key);m.setup.count=m.MaximumPlayers;if(m.TeamSport)m.teamA=m.teamB=4;m.NormalizeSetup();for(int i=0;i<m.setup.count;i++){m.setup.players[i].name="LONG RACER NAME "+(i+1);m.setup.players[i].source=BowlingSource.AI;}m.Save();yield return Delay(.2f);foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Screen.SetResolution(size.x,size.y,false);yield return Delay(.3f);CheckText(m.menus.pages[0],key+" setup "+size.x);if(cycle==0)Capture(key+"-setup-"+size.x);yield return Delay(.1f);}Check(m.StartMatch(),"maximum all-AI rematch "+key);yield return Delay(1.3f);if(cycle==0)Capture(key+"-play-1080");yield return Delay(.2f);m.Pause();yield return Delay(.2f);Check(m.Paused&&Time.timeScale==0,"pause "+key);CheckText(m.menus.pages[3],key+" pause");m.Resume();yield return Delay(.2f);Check(m.Live,"resume "+key);m.SetupScreen();Check(m.StartMatch(),"second immediate rematch "+key);yield return Delay(.2f);}SportsNavigation.FrontEnd();yield return Delay(.7f);front=FindAnyObjectByType<SportsFrontEnd>();Check(front!=null&&Time.timeScale==1&&FindObjectsByType<DigitalRuby.WeatherMaker.WeatherMakerScript>(FindObjectsInactive.Include).Length==0,"collection return "+key+" cycle"+cycle);}
  front.Action("play");Screen.SetResolution(1280,720,false);yield return Delay(.4f);Capture("final-selection-720");yield return Delay(.2f);Check(!error,"no runtime exceptions across26 sport transitions and event rematches");}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}}
